def minDeletionSize(A):
    if not A:
        return 0

    n_cols = len(A[0])
    # dp[j] will store the maximum number of columns we can keep
    # ending at column j, such that all rows remain non-decreasing.
    dp = [1] * n_cols

    for j in range(n_cols):
        for i in range(j):
            # Check if keeping column i and column j maintains lexicographic order for all rows
            valid = True
            for row in A:
                if row[i] > row[j]:
                    valid = False
                    break

            if valid:
                dp[j] = max(dp[j], dp[i] + 1)

    max_kept = max(dp)
    return n_cols - max_kept
